{"file_path":"safety_evals/loader.py","content":""""Loading and preparing safety-monitor transcript logs."""


def parse_transcript_log(lines):
    """Parse comma-separated ``id,day,flagged`` transcript log lines."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")
        id_, day_text, flag_text = fields
        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc

        if flag_text == "1":
            flagged = True
        elif flag_text == "0":
            flagged = False
        elif flag_text == "":
            flagged = None
        else:
            raise ValueError(f"line {line_number}: flagged must be 1, 0, or empty")

        out.append({"id": id_, "day": day, "flagged": flagged})
    return out


def dedupe_transcripts(events):
    """Keep the last transcript for each id, sorted by day and then id."""
    latest = {}
    for event in events:
        latest[event["id"]] = event
    return sorted(latest.values(), key=lambda event: (event["day"], event["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Count flagged transcripts on each day in the inclusive day range."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["flagged"] is True:
            counts[day - start_day] += 1
    return counts
"}

{"file_path":"safety_evals/report.py","content":""""Reports and group-level summaries for monitor evaluation."""
from safety_evals.loader import daily_flag_counts
from safety_evals.metrics import (
    flags_in_window,
    monitor_flag_rate,
    pooled_flag_rate,
)


def monitor_summary(groups, days):
    """Summarize pooled rate, recent flags, and non-empty group count."""
    all_events = [event for group in groups.values() for event in group]
    if all_events:
        first_day = min(event["day"] for event in all_events)
        last_day = max(event["day"] for event in all_events)
        daily_counts = daily_flag_counts(all_events, first_day, last_day)
        recent = flags_in_window(daily_counts, days)
    else:
        recent = 0

    non_empty_groups = sum(bool(group) for group in groups.values())
    return {
        "rate": round(pooled_flag_rate(groups), 3),
        "recent": recent,
        "groups": non_empty_groups,
    }


def top_flagged_groups(groups, n):
    """Return up to ``n`` non-empty groups by rate, with name tie-breaking."""
    ranked = [name for name, events in groups.items() if events]
    ranked.sort(key=lambda name: (-monitor_flag_rate(groups[name]), name))
    return ranked[:n]
